% Paper-ready top38 XRV AUROC figures in MATLAB.
% Exact ROC coordinates are read from top38_xrv_roc_all.mat, generated by
% 049_top38_paper_roc.py.  The 12th tile is reserved for the shared legend.

clear; close all;
here = fileparts(mfilename('fullpath'));
resultRoot = fullfile(here, '..', 'RESULT_20261109_120931', ...
    'evaluation_balanced');
arms = {'eps1', 'eps10'};
pathologies = {'Atelectasis', 'Consolidation', 'Pneumothorax', 'Edema', ...
    'Effusion', 'Pneumonia', 'Cardiomegaly', 'Lung Lesion', 'Fracture', ...
    'Lung Opacity', 'Enlarged Cardiomediastinum'};

for a = 1:numel(arms)
    arm = arms{a};
    outDir = fullfile(resultRoot, arm, 'filtered_top38');
    D = load(fullfile(outDir, 'top38_xrv_roc_all.mat'));

    fig = figure('Color', 'w', 'Units', 'inches', ...
        'Position', [0.5 0.5 8.0 6.6]);
    tl = tiledlayout(fig, 3, 4, 'TileSpacing', 'compact', ...
        'Padding', 'compact');

    for k = 1:numel(pathologies)
        ax = nexttile(tl, k);
        plot(ax, D.real_fpr{k}, D.real_tpr{k}, '--', ...
            'Color', [0.078 0.333 0.753], 'LineWidth', 2.6); hold(ax, 'on');
        plot(ax, D.synthetic_fpr{k}, D.synthetic_tpr{k}, '-', ...
            'Color', [0.776 0.157 0.157], 'LineWidth', 2.6);
        plot(ax, [0 1], [0 1], ':', 'Color', [0.33 0.33 0.33], ...
            'LineWidth', 1.3);
        title(ax, pathologies{k}, 'FontSize', 14, 'FontWeight', 'bold');
        xlim(ax, [0 1]); ylim(ax, [0 1]);
        xticks(ax, [0 .5 1]); yticks(ax, [0 .5 1]);
        xlabel(ax, 'FPR', 'FontSize', 11); ylabel(ax, 'TPR', 'FontSize', 11);
        set(ax, 'FontSize', 9, 'Box', 'on', 'LineWidth', 1.0);
        grid(ax, 'on'); ax.GridAlpha = 0.16;
    end

    % Shared legend in the final unused tile.
    ax = nexttile(tl, 12); axis(ax, 'off'); hold(ax, 'on');
    hSyn = plot(ax, nan, nan, '-', 'Color', [0.776 0.157 0.157], 'LineWidth', 2.8);
    hReal = plot(ax, nan, nan, '--', 'Color', [0.078 0.333 0.753], 'LineWidth', 2.8);
    hChance = plot(ax, nan, nan, ':', 'Color', [0.33 0.33 0.33], 'LineWidth', 1.5);
    legend(ax, [hSyn hReal hChance], {'Synthetic', 'Real', 'Chance'}, ...
        'Location', 'northwest', 'Box', 'off', 'FontSize', 13);

    exportgraphics(fig, fullfile(outDir, ...
        'label_auroc_roc_all_paper_matlab.png'), 'Resolution', 450);
    savefig(fig, fullfile(outDir, 'label_auroc_roc_all_paper_matlab.fig'));
    close(fig);
end
